/**
 * Client-Side Configuration Manager
 * Handles configuration persistence in local device storage with API key management
 */

import type { ApiKeys, Config, DashboardState, FeatureBlueprintDefaults, HelpState } from '@char-gen/shared';
import {
  createDefaultChubConfig,
  createDefaultComfyUIConfig,
  type ChubConfig,
  type ComfyUIConfig,
} from '@char-gen/shared';
import { createDefaultDashboard, normalizeDashboard } from '../dashboard.js';
import { readPersistedString, removePersistedValues, writePersistedString } from '../persistence/storage.js';
import { normalizePaneWidths } from '../split-pane.js';
import { DEFAULT_FEATURE_BLUEPRINT_PATHS } from '@/lib/blueprints/defaults';

// The legacy `bpui.*` fallbacks are gone: `migrateLegacyStorageKeys` moves any
// stragglers onto these keys at startup (see `lib/persistence/migrate-legacy-keys.ts`).
const CONFIG_STORAGE_KEY = 'eidolon.web.config';
const API_KEYS_STORAGE_KEY = 'eidolon.web.apiKeys';
const API_KEYS_PERSISTENCE_KEY = 'eidolon.web.apiKeys.persist';
const CONFIG_CHANGED_EVENT = 'eidolon:config-changed';

/**
 * In-memory API keys storage (cleared on page refresh by default)
 * Can be persisted to local device storage with user consent
 */
let sessionApiKeys: ApiKeys = {};

const LEGACY_FEATURE_BLUEPRINT_PATHS: Record<string, string> = {
  generator: 'blueprints/system/generator.md',
  rpbotgenerator: 'blueprints/system/generator.md',
  seed_generator: 'blueprints/system/seed_generator.md',
  offspring_generator: 'blueprints/system/offspring_generator.md',
  lorebook_generator: 'blueprints/system/lorebook_generator.md',
  worldbook_generator: 'blueprints/system/lorebook_generator.md',
  intro_scene: 'blueprints/system/intro_scene.md',
};

const CORRUPTED_API_KEY_PATTERNS = [
  /^window\.fetch:/i,
  /cannot convert value in record<bytestring/i,
  /^bearer\s+window\.fetch:/i,
];

export function normalizeApiKeyValue(value: string): string {
  return value
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .trim()
    .replace(/^['"]+|['"]+$/g, '');
}

export function isInvalidApiKeyValue(value: string): boolean {
  if (!value) {
    return true;
  }

  if (/[^\x20-\x7E]/.test(value)) {
    return true;
  }

  if (/\r|\n/.test(value)) {
    return true;
  }

  return CORRUPTED_API_KEY_PATTERNS.some((pattern) => pattern.test(value));
}

function readStoredValue(keys: readonly string[]): { value: string; sourceKey: string } | null {
  return readPersistedString(keys);
}

function writeStoredValue(currentKey: string, legacyKeys: readonly string[], value: string): void {
  writePersistedString(currentKey, legacyKeys, value);
}

function removeStoredValues(keys: readonly string[]): void {
  removePersistedValues(keys);
}

function dispatchConfigChangedEvent(): void {
  if (typeof window === 'undefined') {
    return;
  }

  window.dispatchEvent(new Event(CONFIG_CHANGED_EVENT));
}

function normalizeApiKeys(keys: ApiKeys): ApiKeys {
  return Object.fromEntries(
    Object.entries(keys)
      .map(([provider, key]) => [provider, typeof key === 'string' ? normalizeApiKeyValue(key) : key])
      .filter(([, key]) => typeof key === 'string' && !isInvalidApiKeyValue(key))
      .filter(([, key]) => typeof key === 'string' && key.length > 0),
  );
}

function normalizeFeatureBlueprintDefaults(defaults?: FeatureBlueprintDefaults): FeatureBlueprintDefaults | undefined {
  if (!defaults) {
    return defaults;
  }

  return Object.fromEntries(
    Object.entries(defaults).map(([feature, value]) => {
      if (typeof value !== 'string' || value.length === 0) {
        return [feature, value];
      }

      return [feature, LEGACY_FEATURE_BLUEPRINT_PATHS[value] ?? value];
    }),
  ) as FeatureBlueprintDefaults;
}
let persistKeys = false;

export interface ConfigManagerOptions {
  /**
   * Whether to persist API keys to localStorage
   * Default: false (keys only in memory)
   */
  persistApiKeys?: boolean;
}

function createDefaultHelpState(): HelpState {
  return {
    first_run_completed: false,
    show_inline_tips: true,
    completed_guides: [],
    dismissed_tips: [],
    completed_tours: [],
  };
}

/**
 * Client-side configuration manager
 */
export class ConfigManager {
  private config: Config;
  private options: ConfigManagerOptions;

  constructor(options: ConfigManagerOptions = {}) {
    this.options = {
      persistApiKeys: false,
      ...options,
    };

    persistKeys = this.loadPersistPreference(this.options.persistApiKeys || false);

    // Load config from local device storage or use defaults
    this.config = this.loadConfig();
    this.loadPersistedApiKeys();
  }

  private mergeConfig(config: Partial<Config>): Config {
    const defaults = this.getDefaultConfig();

    return {
      ...defaults,
      ...config,
      batch: {
        ...defaults.batch,
        ...(config.batch ?? {}),
      },
      help: config.help ? { ...defaults.help, ...config.help } : defaults.help,
      // Normalized rather than spread: a stored layout outlives the registry that wrote
      // it, so the reader decides what is valid (see `lib/dashboard.ts`).
      dashboard: normalizeDashboard(config.dashboard),
      // Same reasoning for pane widths: a stored pixel value is only meaningful against
      // the container it was dragged inside, so it is validated here and clamped again at
      // render time (see `lib/split-pane.ts`).
      pane_widths: normalizePaneWidths(config.pane_widths),
      feature_blueprints: {
        ...defaults.feature_blueprints,
        ...(normalizeFeatureBlueprintDefaults(config.feature_blueprints) ?? {}),
      },
      comfyui: {
        ...defaults.comfyui!,
        ...(config.comfyui ?? {}),
      },
      chub: {
        ...defaults.chub!,
        ...(config.chub ?? {}),
      },
    };
  }

  private loadPersistPreference(defaultValue: boolean): boolean {
    try {
      const stored = readStoredValue([API_KEYS_PERSISTENCE_KEY]);
      if (stored && stored.sourceKey !== API_KEYS_PERSISTENCE_KEY) {
        writeStoredValue(API_KEYS_PERSISTENCE_KEY, [], stored.value);
      }

      if (stored?.value === 'true') {
        return true;
      }
      if (stored?.value === 'false') {
        return false;
      }
    } catch {
      // Ignore parse errors
    }

    return defaultValue;
  }

  private savePersistPreference(value: boolean): void {
    try {
      writeStoredValue(API_KEYS_PERSISTENCE_KEY, [], String(value));
    } catch (error) {
      console.warn('Failed to save API key persistence preference:', error);
    }
  }

  private loadConfig(): Config {
    try {
      const stored = readStoredValue([CONFIG_STORAGE_KEY]);
      if (stored) {
        const parsed = this.mergeConfig(JSON.parse(stored.value) as Config);
        if (stored.sourceKey !== CONFIG_STORAGE_KEY) {
          writeStoredValue(CONFIG_STORAGE_KEY, [], JSON.stringify(parsed));
        }
        return parsed;
      }
    } catch {
      // Ignore parse errors
    }

    return this.getDefaultConfig();
  }

  private saveConfig(): void {
    try {
      writeStoredValue(CONFIG_STORAGE_KEY, [], JSON.stringify(this.config));
      dispatchConfigChangedEvent();
    } catch (error) {
      console.warn('Failed to save config to device storage:', error);
    }
  }

  private getDefaultConfig(): Config {
    return {
      engine: 'openai_compatible',
      engine_mode: 'auto',
      // Ollama Cloud ids must match GET https://ollama.com/api/tags exactly, so the
      // default carries the tag (`gemma4:31b`, not `gemma4`). Keyless local servers
      // use the Custom provider with http://localhost:11434/v1 in Settings → Runtime.
      model: 'gemma4:31b',
      temperature: 0.7,
      max_tokens: 4096,
      api_keys: {},
      batch: {
        max_concurrent: 3,
        rate_limit_delay: 1,
      },
      help: createDefaultHelpState(),
      dashboard: createDefaultDashboard(),
      pane_widths: {},
      feature_blueprints: {
        ...DEFAULT_FEATURE_BLUEPRINT_PATHS,
      },
      comfyui: createDefaultComfyUIConfig(),
      chub: createDefaultChubConfig(),
    };
  }

  /**
   * Get the current configuration
   */
  getConfig(): Config {
    return this.mergeConfig(this.config);
  }

  getHelpState(): HelpState {
    return {
      ...(this.config.help ?? createDefaultHelpState()),
      completed_guides: [...(this.config.help?.completed_guides ?? [])],
      dismissed_tips: [...(this.config.help?.dismissed_tips ?? [])],
      completed_tours: [...(this.config.help?.completed_tours ?? [])],
    };
  }

  /**
   * Get API keys (from session or persisted local storage)
   */
  getApiKeys(): ApiKeys {
    return normalizeApiKeys(sessionApiKeys);
  }

  /**
   * Get a specific API key
   */
  getApiKey(provider: string): string | undefined {
    const key = sessionApiKeys[provider];
    return typeof key === 'string' ? normalizeApiKeyValue(key) : undefined;
  }

  /**
   * Set an API key (stored in session, persisted if enabled)
   */
  setApiKey(provider: string, key: string): void {
    const normalizedKey = normalizeApiKeyValue(key);
    if (normalizedKey) {
      sessionApiKeys[provider] = normalizedKey;
    } else {
      delete sessionApiKeys[provider];
    }
    this.persistApiKeysIfNeeded();
    dispatchConfigChangedEvent();
  }

  /**
   * Set multiple API keys
   */
  setApiKeys(keys: ApiKeys): void {
    sessionApiKeys = {
      ...normalizeApiKeys(sessionApiKeys),
      ...normalizeApiKeys(keys),
    };
    this.persistApiKeysIfNeeded();
    dispatchConfigChangedEvent();
  }

  /**
   * Replace the full API key set.
   */
  replaceApiKeys(keys: ApiKeys): void {
    sessionApiKeys = normalizeApiKeys(keys);
    this.persistApiKeysIfNeeded();
    dispatchConfigChangedEvent();
  }

  /**
   * Clear an API key
   */
  clearApiKey(provider: string): void {
    delete sessionApiKeys[provider];
    this.persistApiKeysIfNeeded();
    dispatchConfigChangedEvent();
  }

  /**
   * Clear all API keys
   */
  clearAllApiKeys(): void {
    sessionApiKeys = {};
    this.persistApiKeysIfNeeded();
    dispatchConfigChangedEvent();
  }

  /**
   * Load API keys from persisted local storage (for persistence mode)
   */
  private loadPersistedApiKeys(): void {
    if (!persistKeys) {
      return;
    }

    try {
      const stored = readStoredValue([API_KEYS_STORAGE_KEY]);
      if (stored) {
        const parsed = normalizeApiKeys(JSON.parse(stored.value) as ApiKeys);
        sessionApiKeys = parsed;
        if (stored.sourceKey !== API_KEYS_STORAGE_KEY) {
          writeStoredValue(API_KEYS_STORAGE_KEY, [], JSON.stringify(parsed));
        }
      }
    } catch {
      // Ignore parse errors
    }
  }

  /**
   * Persist API keys to local storage if enabled
   */
  private persistApiKeysIfNeeded(): void {
    if (persistKeys) {
      try {
        writeStoredValue(API_KEYS_STORAGE_KEY, [], JSON.stringify(normalizeApiKeys(sessionApiKeys)));
      } catch (error) {
        console.warn('Failed to persist API keys:', error);
      }
    }
  }

  /**
   * Toggle API key persistence
   */
  setPersistApiKeys(persist: boolean): void {
    persistKeys = persist;
    this.savePersistPreference(persist);

    if (persist) {
      this.persistApiKeysIfNeeded();
    } else {
      // Clear persisted keys if disabling persistence
      try {
        removeStoredValues([API_KEYS_STORAGE_KEY]);
      } catch {
        // Ignore errors
      }
    }
  }

  /**
   * Check if API keys are being persisted
   */
  isPersistingApiKeys(): boolean {
    return persistKeys;
  }

  /**
   * Export API keys as JSON (for backup)
   */
  exportApiKeys(): string {
    return JSON.stringify(normalizeApiKeys(sessionApiKeys), null, 2);
  }

  /**
   * Import API keys from JSON (for restore)
   */
  importApiKeys(json: string): void {
    try {
      const keys = JSON.parse(json) as ApiKeys;
      sessionApiKeys = normalizeApiKeys(keys);
      this.persistApiKeysIfNeeded();
    } catch {
      throw new Error('Invalid API keys JSON');
    }
  }

  /**
   * Update configuration
   */
  updateConfig(updates: Partial<Config>): void {
    this.config = this.mergeConfig({
      ...this.config,
      ...updates,
      batch: {
        ...this.config.batch,
        ...(updates.batch ?? {}),
      },
      help: {
        ...this.getHelpState(),
        ...(updates.help ?? {}),
      },
      feature_blueprints: {
        ...(this.config.feature_blueprints ?? {}),
        ...(normalizeFeatureBlueprintDefaults(updates.feature_blueprints) ?? {}),
      },
      comfyui: {
        ...(this.config.comfyui ?? createDefaultComfyUIConfig()),
        ...(updates.comfyui ?? {}),
      },
      chub: {
        ...(this.config.chub ?? createDefaultChubConfig()),
        ...(updates.chub ?? {}),
      },
    });
    this.saveConfig();
  }

  /**
   * Update the ComfyUI handoff settings (Settings → Image Pipeline and the render panel).
   */
  updateComfyUIConfig(updates: Partial<ComfyUIConfig>): void {
    this.updateConfig({
      comfyui: {
        ...(this.config.comfyui ?? createDefaultComfyUIConfig()),
        ...updates,
      },
    });
  }

  /**
   * Update the Chub account/publish settings (Settings → Chub and the publish panel).
   */
  updateChubConfig(updates: Partial<ChubConfig>): void {
    this.updateConfig({
      chub: {
        ...(this.config.chub ?? createDefaultChubConfig()),
        ...updates,
      },
    });
  }

  updateHelpState(updates: Partial<HelpState>): void {
    this.updateConfig({
      help: {
        ...this.getHelpState(),
        ...updates,
      },
    });
  }

  resetHelpState(): void {
    this.updateConfig({ help: createDefaultHelpState() });
  }

  getDashboard(): DashboardState {
    return normalizeDashboard(this.config.dashboard);
  }

  /**
   * Replaces the Home dashboard layout.
   *
   * Normalized on the way in as well as on the way out, so a caller cannot persist a
   * shape that the renderer would then have to defend against.
   */
  updateDashboard(state: DashboardState): void {
    this.updateConfig({ dashboard: normalizeDashboard(state) });
  }

  resetDashboard(): void {
    this.updateConfig({ dashboard: createDefaultDashboard() });
  }

  getPaneWidths(): Record<string, number> {
    return normalizePaneWidths(this.config.pane_widths);
  }

  /** `undefined` when this pane has never been dragged, so callers can apply their own default. */
  getPaneWidth(paneId: string): number | undefined {
    return this.getPaneWidths()[paneId];
  }

  /**
   * Remembers a pane width, normalized on the way in as well as on the way out — a caller
   * cannot persist a value the renderer would then have to defend against.
   */
  updatePaneWidth(paneId: string, width: number): void {
    this.updateConfig({ pane_widths: normalizePaneWidths({ ...this.getPaneWidths(), [paneId]: width }) });
  }

  /**
   * Reset configuration to defaults
   */
  resetConfig(): void {
    this.config = this.getDefaultConfig();
    this.saveConfig();
  }

  /**
   * Export configuration as JSON
   */
  exportConfig(): string {
    const exportData = {
      config: this.config,
      version: '1.0',
      exportedAt: new Date().toISOString(),
    };
    return JSON.stringify(exportData, null, 2);
  }

  /**
   * Import configuration from JSON
   */
  importConfig(json: string): void {
    try {
      const data = JSON.parse(json);
      if (data.config) {
        this.config = this.mergeConfig(data.config as Config);
        this.saveConfig();
      }
    } catch {
      throw new Error('Invalid configuration JSON');
    }
  }

  /**
   * Clear all stored data (config and API keys)
   */
  clearAll(): void {
    this.config = this.getDefaultConfig();
    sessionApiKeys = {};
    persistKeys = false;
    try {
      removeStoredValues([CONFIG_STORAGE_KEY]);
      removeStoredValues([API_KEYS_STORAGE_KEY]);
      removeStoredValues([API_KEYS_PERSISTENCE_KEY]);
    } catch {
      // Ignore errors
    }
  }
}

export const CONFIG_MANAGER_CHANGED_EVENT = CONFIG_CHANGED_EVENT;

// Global instance
export const configManager = new ConfigManager();

/**
 * Get API keys for use in API headers (base64 encoded)
 */
export function getApiKeysHeader(): Record<string, string> | undefined {
  const keys = configManager.getApiKeys();
  if (Object.keys(keys).length === 0) {
    return undefined;
  }

  // Encode as base64 for safe transmission
  const encoded = btoa(JSON.stringify(keys));
  return {
    'X-BPUI-API-KEYS': encoded,
  };
}

/**
 * Parse API keys from header value
 */
export function parseApiKeysHeader(header: string): ApiKeys {
  try {
    const decoded = atob(header);
    return JSON.parse(decoded) as ApiKeys;
  } catch {
    return {};
  }
}
